package com.aditya.day13.payment; import jakarta.persistence.*; import java.util.*; @Entity public class Payment{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;UUID orderId;double amount;@Column(unique=true)String idempotencyKey;String status;public UUID getId(){return id;}public void setOrderId(UUID x){orderId=x;}public UUID getOrderId(){return orderId;}public void setAmount(double x){amount=x;}public double getAmount(){return amount;}public void setIdempotencyKey(String x){idempotencyKey=x;}public String getIdempotencyKey(){return idempotencyKey;}public void setStatus(String x){status=x;}public String getStatus(){return status;}}